//! Parity with Python jieba_fast 0.53. Fixtures are generated by
//! `parity/gen_fixtures.py`; see that script for the format.

use std::path::PathBuf;

use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
  text: String,
  lcut: Vec<usize>,
  search: Option<Vec<String>>,
  pos: Option<Vec<usize>>,
  flags: String,
}

const SETS: &[&str] = &["hand", "corpus", "prose", "words", "hmm", "mixed", "long"];

/// Documented mismatches as `(set, text)`. Empty: there are none.
const EXCEPTIONS: &[(&str, &str)] = &[];

fn load(set: &str) -> Vec<Case> {
  let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(format!("tests/fixtures/{set}.jsonl"));
  let data = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
  data
    .lines()
    .map(|l| serde_json::from_str(l).unwrap_or_else(|e| panic!("{set}: {e}: {l}")))
    .collect()
}

fn split_lengths(text: &str, lengths: &[usize]) -> Vec<String> {
  let chars: Vec<char> = text.chars().collect();
  let mut out = Vec::with_capacity(lengths.len());
  let mut i = 0;
  for &n in lengths {
    out.push(chars[i..i + n].iter().collect());
    i += n;
  }
  assert_eq!(i, chars.len(), "fixture lengths do not cover {text:?}");
  out
}

#[test]
fn parity() {
  let mut failures = Vec::new();
  let mut report = Vec::new();
  for &set in SETS {
    let cases = load(set);
    let mut matched = [0usize; 3];
    for case in &cases {
      let lcut = split_lengths(&case.text, &case.lcut);
      let search = case.search.clone().unwrap_or_else(|| lcut.clone());
      let pos_words = case
        .pos
        .as_ref()
        .map_or_else(|| lcut.clone(), |p| split_lengths(&case.text, p));
      let flags: Vec<&str> = if case.flags.is_empty() {
        Vec::new()
      } else {
        case.flags.split(' ').collect()
      };
      assert_eq!(pos_words.len(), flags.len());
      let pos: Vec<(String, String)> = pos_words
        .into_iter()
        .zip(flags.iter().map(|f| f.to_string()))
        .collect();

      let got_lcut = jieba_fast::lcut(&case.text, true);
      let got_search = jieba_fast::lcut_for_search(&case.text, true);
      let got_pos: Vec<(String, String)> = jieba_fast::posseg::lcut(&case.text, true)
        .into_iter()
        .map(|p| (p.word, p.flag))
        .collect();

      let ok = [got_lcut == lcut, got_search == search, got_pos == pos];
      for (m, o) in matched.iter_mut().zip(ok) {
        *m += o as usize;
      }
      let expected_mismatch = EXCEPTIONS.contains(&(set, case.text.as_str()));
      if ok.iter().all(|&o| o) == expected_mismatch {
        failures.push(format!(
          "[{set}] {:?}\n  lcut ok={} got {got_lcut:?}\n       want {lcut:?}\n  search ok={} got {got_search:?}\n         want {search:?}\n  posseg ok={} got {got_pos:?}\n         want {pos:?}",
          case.text, ok[0], ok[1], ok[2]
        ));
      }
    }
    report.push(format!(
      "{set}: {} cases, lcut {}, cut_for_search {}, posseg {}",
      cases.len(),
      matched[0],
      matched[1],
      matched[2]
    ));
  }
  for line in &report {
    eprintln!("{line}");
  }
  let shown: Vec<&String> = failures.iter().take(20).collect();
  assert!(
    failures.is_empty(),
    "{} mismatches (first {}):\n{}",
    failures.len(),
    shown.len(),
    shown
      .iter()
      .map(|s| s.as_str())
      .collect::<Vec<_>>()
      .join("\n")
  );
}

#[test]
fn tables_load() {
  assert_eq!(jieba_fast::dt.total, 60_101_967);
  assert_eq!(jieba_fast::posseg::MODEL.states.len(), 256);
  assert_eq!(jieba_fast::posseg::MODEL.char_state_tab.len(), 6648);
  assert_eq!(jieba_fast::get_FREQ("中华人民共和国"), Some(9989));
  assert_eq!(jieba_fast::dt.FREQ.len(), 498_113);
}
